import java.util.*;class Solution{static class N{N[]c=new N[26];String w;}List<String>o=new ArrayList<>();void f(char[][]b,int i,int j,N p){if(i<0||j<0||i==b.length||j==b[0].length||b[i][j]=='#')return;p=p.c[b[i][j]-'a'];if(p==null)return;if(p.w!=null){o.add(p.w);p.w=null;}char c=b[i][j];b[i][j]='#';f(b,i+1,j,p);f(b,i-1,j,p);f(b,i,j+1,p);f(b,i,j-1,p);b[i][j]=c;}public List<String> findWords(char[][]b,String[]w){N r=new N();for(String s:w){N p=r;for(char c:s.toCharArray()){int k=c-'a';if(p.c[k]==null)p.c[k]=new N();p=p.c[k];}p.w=s;}for(int i=0;i<b.length;i++)for(int j=0;j<b[0].length;j++)f(b,i,j,r);return o;}}
